        private final ChannelHandlerContext ctx;
        private final Object msg;
        private final ChannelPromise promise;

        public CachedMsg(ChannelHandlerContext ctx, Object msg, ChannelPromise promise) {
            this.ctx = ctx;
            this.msg = msg;
            this.promise = promise;
        }
